 o+='<div class="grille">'+kpi(st('encaisse'),'encaissé depuis le début',aide)+kpi(st('a_venir'),'mensualités à venir',aide)+kpi(st('impaye'),'impayé',aide)+kpi(st('rembourse'),'remboursé','paiements en une fois seulement')+'</div>';
